@@ -37,6 +37,16 @@ public function validate(mixed $value, Constraint $constraint): void

         $value = (string) $value;

+        if (str_contains($value, "\0")) {
+            $this->context->buildViolation($constraint->message)
+                ->setParameter('{{ value }}', $this->formatValue($value))
+                ->setParameter('{{ format }}', $this->formatValue($constraint->format))
+                ->setCode(DateTime::INVALID_FORMAT_ERROR)
+                ->addViolation();
+
+            return;
+        }
+
         \DateTimeImmutable::createFromFormat($constraint->format, $value);

         $errors = \DateTimeImmutable::getLastErrors() ?: ['error_count' => 0, 'warnings' => []];

@@ -110,6 +110,8 @@ public static function getInvalidDateTimes()
             ['Y-m-d H:i:s', '2010-01-01 24:00:00', DateTime::INVALID_TIME_ERROR],
             ['Y-m-d H:i:s', '2010-01-01 00:60:00', DateTime::INVALID_TIME_ERROR],
             ['Y-m-d H:i:s', '2010-01-01 00:00:60', DateTime::INVALID_TIME_ERROR],
+            ['Y-m-d H:i:s', "2010-01-01 00:00:00\0", DateTime::INVALID_FORMAT_ERROR],
+            ['Y-m-d', "\0", DateTime::INVALID_FORMAT_ERROR],
         ];
